{
  "resources": [
    {
      "resourceType": "Observation",
      "id": "observation-1",
      "status": "final",
      "code": {
        "text": "Left shoulder and upper arm pain"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Severe pain mainly over the top of the left shoulder and into the mid upper arm, not past the elbow; described as 'shocking', a deep ache with sharp stabs when moving the wrong way. Severity approximately 7–8/10 at night and 5/10 during the day; wakes the patient from sleep. Worse with lying on the left side, abduction, overhead work, and lifting tools. Heat pack helps a little; paracetamol does nothing. Onset is unclear: initially reported as 1–2 weeks, then as at least a month; timeline unreliable."
    },
    {
      "resourceType": "Observation",
      "id": "observation-2",
      "status": "final",
      "code": {
        "text": "Left upper outer shoulder numbness"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports a numb 'dead patch' over the left upper outer shoulder, starting a few days after the pain began."
    },
    {
      "resourceType": "Observation",
      "id": "observation-3",
      "status": "final",
      "code": {
        "text": "Subjective left arm weakness"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports subjective weakness and difficulty lifting a ladder, compensating with the right side."
    },
    {
      "resourceType": "Observation",
      "id": "observation-4",
      "status": "final",
      "code": {
        "text": "Associated and negative neurologic symptoms"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "No neck pain, shooting pain down the arm, tingling in the fingers, hand weakness, or neck stiffness reported."
    },
    {
      "resourceType": "Observation",
      "id": "observation-5",
      "status": "final",
      "code": {
        "text": "Trauma history"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "No trauma recalled. Patient wondered whether he had slept awkwardly on the lounge and noted using a new, heavier cordless drill at work."
    },
    {
      "resourceType": "Observation",
      "id": "observation-6",
      "status": "final",
      "code": {
        "text": "Red flag symptom screen"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Reports no chest pain, shortness of breath, jaw pain, diaphoresis, fever, weight loss, night sweats, recent neck injury, limb heaviness or clumsiness, gait change, or sphincter disturbance."
    },
    {
      "resourceType": "Observation",
      "id": "observation-7",
      "status": "final",
      "code": {
        "text": "Telehealth observations"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Phone consultation only; no observations obtained. Voice comfortable at rest, with occasional pauses or winces when describing movement. Speech and cognition appeared okay, but the patient was vague about dates and contradictory about duration. No audible shortness of breath or cough."
    },
    {
      "resourceType": "Observation",
      "id": "observation-8",
      "status": "final",
      "code": {
        "text": "Chronic back ache"
      },
      "subject": {
        "reference": "Patient/patient-1"
      },
      "valueString": "Briefly reports chronic back ache, attributed by the patient as probably related to ute seats."
    }
  ]
}

